// Ingestion has three entry points and all of them land here:
//   * Gmail Trigger  - one item per email, attachments in "attachment_0", ...
//   * Webhook        - one file in binary field "data" (dashboard upload, curl)
// Both are normalised to N items of { json: <metadata>, binary: { data } },
// one item per invoice file, so every node downstream stays entry-point
// agnostic and never has to know where the file came from.

const MIN_EMAIL_BYTES = 50 * 1024;  // below this it's a signature logo, not an invoice
const MAX_PER_EMAIL = 10;           // guard against an attachment bomb
const ALLOWED_MIME = /^(application\/pdf|image\/(png|jpe?g|tiff?|bmp|webp))$/i;

function sizeOf(b) {
  // Default binary mode keeps base64 in `.data`; 4 base64 chars == 3 bytes.
  if (typeof b.data === 'string' && b.data.length) {
    return Math.floor((b.data.length * 3) / 4);
  }
  const n = Number(b.fileSize);
  return Number.isFinite(n) ? n : 0;
}

const out = [];

for (const item of $input.all()) {
  const json = item.json || {};
  const binaries = item.binary || {};

  // Only Gmail items carry a message id - that's how the two paths are told apart.
  const messageId = json.id || json.messageId || null;
  const headers = json.headers || {};
  const emailFrom = headers.from || json.from || null;
  const emailSubject = headers.subject || json.subject || null;
  const isEmail = Boolean(messageId);

  const keys = Object.keys(binaries);
  if (keys.length === 0) {
    // An email with no attachment is normal (body-only receipts, replies) and
    // is not an error - there is simply nothing to ingest. A webhook POST with
    // no file is a caller mistake and should be loud.
    if (isEmail) continue;
    throw new Error('No file uploaded. Expected binary data in "data" field.');
  }

  // Skip attachments already ingested from this same email. The unique index
  // from migration 009 is the real guarantee; this pre-check only avoids
  // burning an OCR + LLM call and an error-handler Slack ping on the common
  // "forwarded twice" case. If the check itself fails we deliberately proceed:
  // dropping an invoice is worse than risking a duplicate the DB will reject.
  let seen = new Set();
  if (isEmail) {
    try {
      const rows = await this.helpers.httpRequest({
        method: 'GET',
        url: `${$env.SUPABASE_URL}/rest/v1/invoices`,
        qs: {
          source_message_id: `eq.${messageId}`,
          select: 'source_attachment_name',
        },
        headers: {
          apikey: $env.SUPABASE_SECRET_KEY,
          Authorization: `Bearer ${$env.SUPABASE_SECRET_KEY}`,
        },
        json: true,
      });
      seen = new Set((rows || []).map((r) => r.source_attachment_name).filter(Boolean));
    } catch (e) {
      console.log(`Dedupe pre-check failed (${e.message}); relying on the unique index.`);
    }
  }

  let taken = 0;
  for (const key of keys) {
    if (taken >= MAX_PER_EMAIL) break;
    const b = binaries[key];
    if (!b) continue;

    const mimeType = String(b.mimeType || 'application/pdf').split(';')[0].trim();
    const originalName = b.fileName || `invoice-${Date.now()}-${out.length}`;

    // Filters apply to email only. A file uploaded by hand through the
    // dashboard or curl was chosen deliberately, so it is never second-guessed
    // on size or type - otherwise a small test invoice would vanish silently.
    if (isEmail) {
      if (!ALLOWED_MIME.test(mimeType)) continue;
      if (sizeOf(b) < MIN_EMAIL_BYTES) continue;   // signature logo, not an invoice
      if (seen.has(originalName)) continue;        // already ingested from this email
    }

    const fileExtension = (originalName.includes('.') ? originalName.split('.').pop() : 'pdf').toLowerCase();
    const safeName = originalName.replace(/[^a-zA-Z0-9._-]/g, '_').replace(/_+/g, '_').replace(/^_+/, '').slice(-80);
    // `out.length` disambiguates attachments that arrive in the same millisecond.
    const objectKey = `${Date.now()}-${out.length}-${safeName || 'invoice.' + fileExtension}`;

    out.push({
      json: {
        originalName,
        mimeType,
        fileExtension,
        objectKey,
        sourceMessageId: messageId,
        sourceAttachmentName: isEmail ? originalName : null,
        sourceEmailFrom: emailFrom,
        sourceEmailSubject: emailSubject,
      },
      binary: { data: b },
    });
    taken++;
  }
}

// Returning [] stops this run cleanly (an email of signature logos, or one
// whose attachments were all ingested already) rather than pushing an empty
// item into OCR and failing downstream for the wrong reason.
return out;

// Runs once per attachment (runOnceForEachItem) so multi-invoice emails keep
// item pairing intact - $input.first() would collapse every attachment onto
// the first OCR result and file the wrong text against the wrong invoice.
const ocrResult = $json;

if (!ocrResult || ocrResult.IsErroredOnProcessing) {
  throw new Error(`OCR failed: ${ocrResult?.ErrorMessage || 'Unknown error'}`);
}

const parsedResults = ocrResult.ParsedResults || [];
if (parsedResults.length === 0) {
  throw new Error('OCR returned no parsed results');
}

const rawText = parsedResults
  .map((page) => page.ParsedText)
  .filter(Boolean)
  .join('\n\n');

if (!rawText || rawText.trim().length === 0) {
  throw new Error('OCR returned empty text');
}

return {
  json: {
    rawText: rawText.trim(),
    pageCount: parsedResults.length,
    ocrConfidence: parsedResults[0]?.FileParseExitCode,
  },
};

// HTTP/Code nodes drop input binary; pull this item's original file back for
// the upload. `.item` (paired item), never `.first()` - with several invoices
// in one email `.first()` would upload the same file against every row.
return {
  json: $json,
  binary: { data: $('Extract File').item.binary.data },
};
